import React, { useState } from 'react';
import './/file-upload.component.css';

function FileUpload() {
  const [selectedFile, setSelectedFile] = useState(null);

  const handleFileChange = (event) => {
    setSelectedFile(event.target.files[0]);
  };

  const handleSubmit = async (event) => {
    event.preventDefault();

    if (selectedFile) {
      const formData = new FormData();
      formData.append('file', selectedFile);

      try {
        const response = await fetch('/upload', { 
          method: 'POST', 
          body: formData 
        });

        if (!response.ok) {
          throw new Error('Network response was not ok');
        }

        const data = await response.json(); 
        console.log('File uploaded successfully:', data);

      } catch (error) {
        console.error('Error uploading file:', error);
      }
    }
  };

  return (
    <div className="container">
      <div className="upload-card">
        <div className="cloud-icon">
          {/* You can use an SVG or an image here */}
          <svg width="60" height="60" viewBox="0 0 100 100">
            <path d="M50 10c-22.1 0-40 17.9-40 40s17.9 40 40 40 40-17.9 40-40-17.9-40-40-40zm0 60c-16.5 0-30-13.5-30-30s13.5-30 30-30 30 13.5 30 30-13.5 30-30 30z" />
            <path d="M50 40l10 10v20l-10 10-10-10v-20z" /> 
          </svg> 
        </div>
        <p className="drag-drop-text">DRAG & DROP</p>
        <p className="drag-drop-text">TO UPLOAD</p>
        <button className="select-files-button">OR, SELECT FILES</button>
        <input 
          type="file" 
          onChange={handleFileChange} 
          className="file-input" 
        />
      </div>
    </div>
  );
}

export default FileUpload;
